 function Future(){const commitments:{label:string;amount:number;date:string}[]=[];const add=(label:string,amount:number,date:string)=>{if(date>=today()&&date<=target)commitments.push({label,amount,date});};pendingParts.forEach(i=>add(i.loan.name+' · '+i.loan.person,i.amountCents-i.paid,i.dueDate));purchases.forEach(c=>add(c.name,balance(c).pendingCents,c.dueDate||''));data.records.filter(r=>r.kind==='bill'&&r.status!=='PAID').forEach(r=>add(r.name,-Math.max(0,r.amountCents-receipts.filter(p=>p.controlId===r.id&&p.direction==='bill-payment').reduce((n,p)=>n+p.amountCents,0)),r.date));recurrences.forEach(c=>{const start=str(c.startDate)||today(),end=[target,str(c.endDate)||target].sort()[0]!;let date=new Date(start.slice(0,7)+'-01T12:00:00');for(let n=0;date.toLocaleDateString('en-CA')<=end&&n<600;n++){const due=new Date(date.getFullYear(),date.getMonth(),Math.min(Number(c.day)||1,new Date(date.getFullYear(),date.getMonth()+1,0).getDate())).toLocaleDateString('en-CA');if(due>=start)add(c.name,(c.nature==='Entrada prevista'?1:-1)*(c.amountCents||0),due);date.setMonth(date.getMonth()+1);}});const incoming=commitments.reduce((n,c)=>n+Math.max(0,c.amount),0),outgoing=commitments.reduce((n,c)=>n+Math.max(0,-c.amount),0),months=Math.max(0,(Number(target.slice(0,4))-Number(today().slice(0,4)))*12+Number(target.slice(5,7))-Number(today().slice(5,7))),contribution=parseMoneyCents(adjust['Aporte mensal a partir das contas (R$)']||'')*months,rate=parseMoneyCents(adjust['Taxa mensal hipotética (%)']||'')/10000,projectedInvestment=Math.round(investmentBalance*Math.pow(1+rate,months)+contribution),extraIn=parseMoneyCents(adjust['Entradas adicionais previstas (R$)']||''),extraOut=parseMoneyCents(adjust['Saídas adicionais previstas (R$)']||''),projectedBank=bankBalance+incoming-outgoing+extraIn-extraOut-contribution;return <>{heading('Futuro','Simule uma data com compromissos conhecidos e ajustes opcionais.')}<Card><Text style={u.h2}>Até quando você quer planejar?</Text><Text style={u.label}>Data desejada</Text><PreviewInput field={{label:'Data desejada',type:'date',required:true,minDate:today()}} value={target} onChange={setTarget}/><View style={{borderTopWidth:1,borderTopColor:C.line,paddingTop:14,marginTop:12}}><Disclosure title="Ajustar aportes e previsões (opcional)">{['Aporte mensal a partir das contas (R$)','Taxa mensal hipotética (%)','Entradas adicionais previstas (R$)','Saídas adicionais previstas (R$)'].map(label=><View key={label} style={{gap:8}}><Text style={u.label}>{label}</Text><PreviewInput field={{label,type:'money'}} value={adjust[label]||''} onChange={v=>setAdjust(p=>({...p,[label]:v}))}/></View>)}</Disclosure></View>{note('Faturas, parcelas futuras reconhecidas, valores a receber e recorrências datadas entram automaticamente. Acrescente aqui somente o que não está cadastrado.')}<Button label="Simular" icon="chart" onPress={()=>{if(target<today()){setError('Escolha uma data a partir de hoje.');return;}setSimulated(true);}}/></Card><Card>{simulated?<>{[['Contas projetadas',projectedBank],['Investimentos projetados',projectedInvestment],['Saldo dos cofrinhos',goalBalance],['Entradas já previstas',incoming+extraIn],['Saídas já previstas',outgoing+extraOut],['Aportes transferidos',contribution],['Total acompanhado',projectedBank+projectedInvestment+goalBalance]].map(([label,n])=><ValueLine key={label} label={String(label)} value={money(Number(n))}/>)}{note('Estimativa até '+dateLabel(target)+'; taxa hipotética, sem promessa de rendimento.')}<Disclosure title={'Ver compromissos incluídos ('+commitments.length+')'}>{commitments.map((c,i)=><ValueLine key={i} label={c.label+' · '+dateLabel(c.date)} value={money(c.amount)}/>)}</Disclosure></>:<View style={{alignItems:'center',paddingVertical:28,paddingHorizontal:12,gap:16}}><Bubble icon="calendar"/><Text style={[u.h2,{fontSize:16}]}>Escolha a data e simule</Text>{note('O resultado mostrará de onde vem cada valor.')}</View>}</Card><Card><View style={between}><Text style={u.h2}>Recorrências previstas</Text><FloatingAdd  label="Recorrência"   onPress={()=>edit('recurrences')}/></View>{recurrences.map(c=><View key={c.id} style={between}><TouchableOpacity style={{flex:1}} onPress={()=>edit('recurrences',c)}><ValueLine label={c.name} value={money(c.amountCents||0)} caption={str(c.nature)+' · dia '+c.day+' · previsão, sem criar lançamento bancário'}/></TouchableOpacity><IconButton icon="trash" label="Excluir recorrência" onPress={()=>open('delete',c)}/></View>)}{!recurrences.length&&<View style={{paddingVertical:22,alignItems:'center'}}>{note('Nenhuma recorrência cadastrada.')}</View>}{note('Previsões apenas para a simulação. Nenhum lançamento ou pagamento bancário é criado.')}</Card></>;}
